for (let iteration = 1; iteration <= maxIterations; iteration += 1) {
  trace.push({ iteration, event: "model_call" });
  try {
    const resource = await generateResource(topic, model);
    if (resource.needsHumanReview) return stop("human_review", trace);
    if (resource.relevanceScore >= 70) return stop("success", trace);
  } catch (error) {
    return stop("error", trace, safeMessage(error));
  }
}
return stop("limit_reached", trace);
